<div class="content-wrapper" style="min-height: 916px;">    <!-- Content Header (Page header) -->    <section class="content-header">        <h1>Danh sách voucher</h1>        <ol class="breadcrumb">            <li><a href="/<?php echo ADMIN_URL; ?>"><i class="fa fa-dashboard"></i> Home</a></li>            <li class="active">Danh Sách voucher</li>        </ol>        <a href="/<?php echo ADMIN_URL; ?>voucher/add"><button style="width: 130px;float: left;margin-right: 10px;" class="btn btn-block btn-primary">Thêm voucher</button></a>        <select class="form-control" id="status" style="width: 150px;float: left;margin-right: 10px;">            <option value=""> -- Trạng thái -- </option>                      <option value="unused"> Chưa sử dụng </option>                      <option value="used"> Đã sử dụng </option>                  </select>            </section>    <br/><br/>    <!-- Main content -->    <section class="content">        <div class="row">            <div class="col-xs-12">                <div class="box" id="list_ajax">                </div>            </div><!-- /.box -->        </div><!-- /.col -->    </section></div><!-- /.row --><script>    var current_pos = <?php echo $pos; ?>;    function loadlist(pos) {        current_pos = pos;        var status = $('#status').val();                $.post('/<?php echo ADMIN_URL; ?>voucher/page', {pos: pos, status: status}, function (results) {            $('#list_ajax').html(results);        });    }    $('#status').change(function () {        loadlist(0);    });       loadlist(current_pos);    $('#list_ajax').on('click', '.pagination a', function () {        var pos = $(this).attr('href').replace('/', '');        loadlist(pos);        return false;    });    function del(id) {        show_dialog('Bạn có muốn xóa voucher id = ' + id + " không", function () {            $.post('/<?php echo ADMIN_URL; ?>voucher/del', {id: id}, function (results) {                loadlist(current_pos);            });        });    }    </script>